public static class Rechner
{
    public static int Berechne(
        int a, int b, string op) => op switch
    {
        "+" => a + b,
        "*" => a * b,
        _ => throw new ArgumentException(
                 "Unbekannter Operator")
    };
}
// Rechner.Berechne(3, 4, "*")  -> 12

private void BtnPlus_Click(
    object sender, RoutedEventArgs e)
{
    int a = int.Parse(txtA.Text);
    int b = int.Parse(txtB.Text);
    lblErgebnis.Text = Rechner
        .Berechne(a, b, "+").ToString();
}

